// SMART CHUNKING SYSTEM FOR N8N CLOUD
// Splits manuscript into safe-sized chunks for TTS processing

const items = $input.all();
const fileData = items[0].binary.data;
const content = Buffer.from(fileData.data, 'base64').toString('utf-8');

// Configuration
const MAX_CHARS = parseInt(items[0].json.chars_per_chunk) || 2000;
const BATCH_SIZE = parseInt(items[0].json.batch_size) || 10;
const bookTitle = items[0].json.book_title;
const outputFolderId = items[0].json.output_drive_folder_id;

console.log('📚 Starting manuscript processing...');
console.log(`   Book: ${bookTitle}`);
console.log(`   Total characters: ${content.length.toLocaleString()}`);

// Split by paragraphs (preserves natural breaks)
const paragraphs = content
  .split(/\n\n+/)
  .map(p => p.trim())
  .filter(p => p.length > 0);

console.log(`   Total paragraphs: ${paragraphs.length}`);

// Create chunks that respect paragraph boundaries
const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

for (const paragraph of paragraphs) {
  const potentialLength = currentChunk.length + paragraph.length + 2;

  if (potentialLength > MAX_CHARS && currentChunk.length > 0) {
    chunks.push({
      index: chunkIndex,
      text: currentChunk.trim(),
      char_count: currentChunk.length,
      word_count: currentChunk.split(/\s+/).length,
      batch: Math.floor(chunkIndex / BATCH_SIZE)
    });
    chunkIndex++;
    currentChunk = paragraph;
  } else {
    currentChunk += (currentChunk ? '\n\n' : '') + paragraph;
  }
}

// Add final chunk
if (currentChunk.length > 0) {
  chunks.push({
    index: chunkIndex,
    text: currentChunk.trim(),
    char_count: currentChunk.length,
    word_count: currentChunk.split(/\s+/).length,
    batch: Math.floor(chunkIndex / BATCH_SIZE)
  });
}

const totalBatches = Math.ceil(chunks.length / BATCH_SIZE);

console.log('✂️  Chunking complete!');
console.log(`   Total chunks: ${chunks.length}`);
console.log(`   Batches: ${totalBatches}`);

// Character and emotion detection
chunks.forEach(chunk => {
  const textLower = chunk.text.toLowerCase();

  // CHARACTER DETECTION
  if (textLower.includes('aaravi') || 
      /she (said|replied|whispered|asked|screamed|shouted)/i.test(chunk.text)) {
    chunk.character = 'aaravi';
  } else if (textLower.includes('vihan') || 
             /he (said|replied|answered|growled|muttered|demanded)/i.test(chunk.text)) {
    chunk.character = 'vihan';
  } else {
    chunk.character = 'narrator';
  }

  // EMOTION DETECTION
  chunk.emotion = 'neutral';

  const emotionPatterns = {
    'happy': /(smiled|laughed|grinned|cheerful|delighted|beamed|joy)/i,
    'sad': /(cried|tears|sobbed|mourned|grief|sorrow)/i,
    'angry': /(shouted|yelled|snarled|snapped|growled|furious|rage)/i,
    'fearful': /(trembled|afraid|terrified|panicked|fear|screamed)/i,
    'determined': /(firmly|resolved|decided|committed|steadfast)/i,
    'loving': /(gently|tenderly|warmly|softly|affection|caressed)/i,
    'protective': /(fierce|defensive|guard|shield|protect)/i
  };

  for (const [emotion, pattern] of Object.entries(emotionPatterns)) {
    if (pattern.test(chunk.text)) {
      chunk.emotion = emotion;
      break;
    }
  }

  // Add metadata
  chunk.book_title = bookTitle;
  chunk.output_folder_id = outputFolderId;
  chunk.estimated_duration_sec = Math.ceil(chunk.word_count / 2.5);
});

const totalMinutes = Math.ceil(chunks.reduce((sum, c) => sum + c.estimated_duration_sec, 0) / 60);
const totalHours = Math.floor(totalMinutes / 60);
const remainingMinutes = totalMinutes % 60;

console.log(`⏱️  Estimated duration: ${totalHours}h ${remainingMinutes}m`);
console.log('🚀 Ready to process!');

return chunks.map(chunk => ({ json: chunk }));

// PROGRESS TRACKER FOR N8N CLOUD
// Creates a summary log for monitoring

const items = $input.all();
const item = items[0];

const progressInfo = {
  chunk_index: item.json.index,
  character: item.json.character,
  emotion: item.json.emotion,
  word_count: item.json.word_count,
  book_title: item.json.book_title,
  file_name: item.json.name,
  file_id: item.json.id,
  timestamp: new Date().toISOString(),
  status: 'completed'
};

const totalChunks = $('Smart Chunking').all().length;
const currentChunk = item.json.index + 1;
const percentage = Math.round((currentChunk / totalChunks) * 100);

console.log(`✅ Chunk ${currentChunk}/${totalChunks} (${percentage}%) - ${item.json.character} [${item.json.emotion}]`);

return [{ json: progressInfo }];

// COMPLETION REPORT FOR N8N CLOUD

const allChunks = $('Smart Chunking').all();
const totalChunks = allChunks.length;

const totalWords = allChunks.reduce((sum, chunk) => sum + chunk.json.word_count, 0);
const totalMinutes = Math.ceil(totalWords / 150); // ~150 words per minute
const hours = Math.floor(totalMinutes / 60);
const minutes = totalMinutes % 60;

const report = {
  status: 'SUCCESS',
  book_title: allChunks[0].json.book_title,
  processing: {
    total_chunks: totalChunks,
    total_words: totalWords,
    estimated_duration: `${hours}h ${minutes}m`,
    completed: new Date().toISOString()
  },
  next_steps: [
    '1. Go to your Google Drive output folder',
    '2. Download all MP3 chunks',
    '3. Use an audio merger tool to combine them:',
    '   - Online: https://audio-joiner.com/',
    '   - Mac Terminal: see instructions below',
    '4. Listen to the complete audiobook',
    '5. Upload to ACX/Audible'
  ],
  mac_merge_instructions: [
    'Open Terminal and navigate to your downloads folder:',
    'cd ~/Downloads/audiobook_chunks',
    '',
    'Merge all MP3s in order:',
    'for f in segment_*.mp3; do echo "file \'$f\'" >> list.txt; done',
    'ffmpeg -f concat -safe 0 -i list.txt -c copy audiobook_complete.mp3',
    '',
    '(FFmpeg must be installed: brew install ffmpeg)'
  ]
};

console.log('\n' + '='.repeat(60));
console.log('🎉 AUDIOBOOK CHUNKS GENERATED!');
console.log('='.repeat(60));
console.log(`📚 Book: ${report.book_title}`);
console.log(`📊 Chunks: ${report.processing.total_chunks}`);
console.log(`📝 Words: ${report.processing.total_words.toLocaleString()}`);
console.log(`⏱️  Duration: ${report.processing.estimated_duration}`);
console.log('='.repeat(60));
console.log('📁 Check your Google Drive output folder for all chunks!');
console.log('='.repeat(60) + '\n');

return [{ json: report }];

// ERROR HANDLER FOR N8N CLOUD

const error = $input.item?.json?.error || { message: 'Unknown error' };

const errorReport = {
  timestamp: new Date().toISOString(),
  chunk_index: $json.index,
  character: $json.character,
  book_title: $json.book_title,
  error_message: error.message,
  text_preview: $json.text?.substring(0, 100) + '...',
  will_retry: true
};

console.error(`❌ Error on chunk ${errorReport.chunk_index}: ${errorReport.error_message}`);
console.error('   Will retry automatically...');

return [{ json: errorReport }];
